typedef struct Entity {
    double x, y;
    void (*update)(struct Entity *self, double dt);   /* the hook */
} Entity;

static void guard_update(Entity *e, double dt) { e->x += 20.0 * dt; }

void world_update(Entity *entities, size_t n, double dt) {
    for (size_t i = 0; i < n; ++i)                    /* the driver walk */
        if (entities[i].update) entities[i].update(&entities[i], dt);
}
